/* Compile against the small host ABI stubs generated by test_net_reentry.py.
 * Fault injection models single-task IPC suspending the main poll mid-frame. */
#include <assert.h>
#include <stdio.h>

#define main q8b_net_driver_main
#include DRIVER_SOURCE
#undef main

static int enabled = 1, polling, pending, in_callback;
static unsigned reentries, wakeups, polls;
static int mock_rx_ready;
static vdevice_t mock_dev;
static proto_funcs_t funcs;
proto_funcs_t *PF = &funcs;

static void deliver(void) {
    in_callback = 1;
    net_check_poll_events(&mock_dev, 0, 0, NULL, NULL);
    in_callback = 0;
}

int ipc_disable(void) {
    assert(!in_callback);
    enabled = 0;
    return 0;
}

void ipc_enable(void) {
    enabled = 1;
    if (pending) {
        pending = 0;
        deliver();
    }
}

void bsp_eth_poll(void) {
    if (polling) {
        reentries++;
        return;
    }
    polling = 1;
    polls++;
    if (!in_callback) {
        if (enabled)
            deliver();
        else
            pending = 1;
    }
    polling = 0;
}

int bsp_eth_init(void) { return 0; }
int bsp_eth_read_mac(uint8_t mac[6]) { memset(mac, 0, 6); return 0; }
int bsp_eth_pending_rx(void) { return mock_rx_ready; }
int bsp_eth_can_write(void) { return 1; }
int bsp_eth_read(void *buf, uint32_t size) { (void)buf; (void)size; return 0; }
int bsp_eth_write(const void *buf, uint32_t size) { (void)buf; return size; }
void bsp_eth_stats(char *buf, uint32_t size) { if (size) buf[0] = 0; }
void klog(const char *fmt, ...) { (void)fmt; }
int usleep(unsigned int n) { (void)n; return 0; }
int vfs_wakeup(uint64_t node, int events) {
    (void)node; (void)events;
    /* A synchronous VFS wake must be able to call back into the driver. */
    assert(enabled && !polling);
    wakeups++;
    deliver();
    return 0;
}
int device_run(vdevice_t *dev, const char *path, int type, int mode, bool multi) {
    (void)dev; (void)path; (void)type; (void)mode; (void)multi;
    return 0;
}

int main(void) {
    _net_dev = &mock_dev;
    for (unsigned i = 0; i < 10000; i++) {
        mock_rx_ready = i & 1;
        net_loop_step(&mock_dev, NULL);
    }
    if (reentries) {
        fprintf(stderr, "FAIL: %u IPC upcalls re-entered an active DMA poll\n", reentries);
        return 1;
    }
    assert(polls >= 20000 && wakeups >= 5000 && enabled && !pending);
    printf("PASS: 10000 injected IPC upcalls; no ring reentry; %u VFS wake callbacks\n", wakeups);
    return 0;
}
